    static void Check(bool value,string why){checks++;if(!value)throw new Exception((context??"setup")+": "+why);}
    static object Get(Dictionary<string,object> row,string key){object value;return row.TryGetValue(key,out value)?value:null;}
    static string Str(Dictionary<string,object> row,string key){return Get(row,key) as string;}
    static long Num(object value){return Convert.ToInt64(value,CultureInfo.InvariantCulture);}
    static List<Dictionary<string,object>> Rows(object value){return ((IEnumerable)value).Cast<Dictionary<string,object>>().ToList();}
    static Dictionary<string,object> Read(string path){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path,Encoding.UTF8));}
    static string Hash(byte[] raw){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(raw)).Replace("-","").ToLowerInvariant();}
    static string Hash(string path){using(var input=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
    static void Plain(string path){var f=new FileInfo(Path.GetFullPath(path));Check(f.Exists&&(f.Attributes&FileAttributes.ReparsePoint)==0,"regular input");for(var p=f.Directory;p!=null;p=p.Parent)Check((p.Attributes&FileAttributes.ReparsePoint)==0,"no linked input ancestor");}
    static string Safe(string root,string relative){Check(!String.IsNullOrEmpty(relative)&&relative.Length<240&&!Path.IsPathRooted(relative)&&!relative.Contains('\\')&&relative.Split('/').All(p=>p!=""&&p!="."&&p!=".."&&p.IndexOf(':')<0),"bounded declared relative path");return RecoveryCatalog.SafeFile(root,relative);}
    static Dictionary<string,string> Binding(string root){return File.Exists(root)?new Dictionary<string,string>{{Path.GetFileName(root),Hash(root)}}:Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p.Substring(root.Length+1),Hash,StringComparer.OrdinalIgnoreCase);}
    static bool Same(Dictionary<string,string> a,Dictionary<string,string> b){return a.Count==b.Count&&a.All(p=>b.ContainsKey(p.Key)&&b[p.Key]==p.Value);}
    static T Guard<T>(Func<CancellationToken,T> action){using(var stop=CancellationTokenSource.CreateLinkedTokenSource(phase)){stop.CancelAfter(TimeSpan.FromMinutes(3));long left=600000-clock.ElapsedMilliseconds;if(left<=0)throw new TimeoutException("Media-only phase watchdog");var task=Task.Run(()=>action(stop.Token));if(Task.WaitAny(new Task[]{task},(int)Math.Min(210000,left))<0){stop.Cancel();throw new TimeoutException("Public call watchdog; completion unconfirmed");}return task.GetAwaiter().GetResult();}}
    static bool Native(ArchiveMessage row){return row.record_kind=="tl_message"&&row.application_confirmed==true&&row.evidence_kind!="fragment"&&row.provenance_verification!="provided_archive_metadata";}
    static void NoLimits(IEnumerable<string> warnings){foreach(string warning in warnings??new string[0])Check(warning==null||new[]{"LIMIT","BUDGET","TIMEOUT","CANCEL","INCOMPLETE"}.All(word=>warning.IndexOf(word,StringComparison.OrdinalIgnoreCase)<0),"no concealed incomplete analysis: "+warning);}
    static string Source(string name){return Safe(inputs,Str(sqlite[name],"path"));}

    static void Extract()
    {
        string root=Path.Combine(project,"tests","fixtures","telegram-media-only");Plain(Path.Combine(root,"manifest.json"));Check(Hash(Path.Combine(root,"manifest.json"))==Manifest,"closed independent manifest");
        var manifest=Read(Path.Combine(root,"manifest.json"));Check(Str(manifest,"telegram_commit")==Commit&&Num(manifest["native_cases"])==14&&Num(manifest["empty_text_cases"])==7&&Num(manifest["nonempty_text_slots"])==7&&Num(manifest["mutation_controls"])==56&&Num(manifest["native_sqlite_sources"])==70,"input facts do not define the new retention policy");
        var members=Rows(manifest["files"]);Check(members.Count==5&&new HashSet<string>(members.Select(r=>Str(r,"path"))).SetEquals(new[]{"oracle.json.gz","native-sqlite-cases.zip","oracle-sources.tar.gz","LICENSE","README.md"}),"exact closed canonical members");
        foreach(var row in members){string path=Safe(root,Str(row,"path"));Plain(path);Check(new FileInfo(path).Length==Num(row["bytes"])&&Hash(path)==Str(row,"sha256"),"canonical member size/SHA");}
        byte[] raw;using(var input=File.OpenRead(Path.Combine(root,"oracle.json.gz")))using(var gzip=new GZipStream(input,CompressionMode.Decompress))using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int n;while((n=gzip.Read(buffer,0,buffer.Length))>0){phase.ThrowIfCancellationRequested();Check(output.Length<=1024*1024-n,"bounded raw oracle");output.Write(buffer,0,n);}raw=output.ToArray();}
        Check(raw.Length==Num(manifest["uncompressed_json_bytes"])&&Hash(raw)==Str(manifest,"uncompressed_json_sha256"),"full independent JSON bytes");var oracle=Json.Deserialize<Dictionary<string,object>>(new UTF8Encoding(false,true).GetString(raw));
        positives=Rows(oracle["positive_cases"]).ToDictionary(r=>Str(r,"name"),StringComparer.Ordinal);controls=Rows(oracle["mutation_controls"]).ToDictionary(r=>Str(r,"name"),StringComparer.Ordinal);sqlite=Rows(oracle["sqlite_sources"]).ToDictionary(r=>Str(r,"case"),StringComparer.Ordinal);
        Check(positives.Count==14&&controls.Count==56&&sqlite.Count==70&&positives.Values.Count(r=>Str(r,"text")=="")==7&&positives.Values.Sum(r=>Num(r["expected_text_slots"]))==7,"fourteen native metadata records and seven exact empty texts; old text-slot oracle unchanged");
        foreach(var row in positives.Values.Concat(controls.Values)){string name=Str(row,"name");byte[] blob=Convert.FromBase64String(Str(row,"blob_base64"));Check(blob.Length==Num(row["bytes"])&&Hash(blob)==Str(row,"blob_sha256")&&Str(sqlite[name],"native_blob_sha256")==Hash(blob),"whole independent BLOB and SQLite binding");if(positives.ContainsKey(name)){Check(Hash(blob.Take((int)Num(row["tl_bytes"])).ToArray())==Str(row,"tl_body_sha256"),"exact body hash");byte[] text=Encoding.UTF8.GetBytes(Str(row,"text"));Check(text.Length==Num(row["text_utf8_bytes"])&&Convert.ToBase64String(text)==Str(row,"text_utf8_base64"),"exact UTF8 text including zero bytes");}else Check(positives.ContainsKey(Str(row,"parent"))&&Num(row["expected_attributed_native_records"])==0,"independently labelled controls retain zero attributed records");}
        string zip=Path.Combine(root,"native-sqlite-cases.zip");Check(Hash(zip)==ZipHash,"exact native ZIP");var declared=sqlite.Values.ToDictionary(r=>Str(r,"path"),StringComparer.Ordinal);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Directory.CreateDirectory(inputs);long total=0;
        using(var archive=new ZipArchive(File.OpenRead(zip),ZipArchiveMode.Read)){Check(archive.Entries.Count==70,"seventy declared SQLite inputs");foreach(var entry in archive.Entries){phase.ThrowIfCancellationRequested();Check(declared.ContainsKey(entry.FullName)&&seen.Add(entry.FullName),"unique declared ZIP member");int mode=(entry.ExternalAttributes>>16)&0xf000;Check((mode==0||mode==0x8000)&&(entry.ExternalAttributes&(int)FileAttributes.ReparsePoint)==0,"regular ZIP file");var row=declared[entry.FullName];Check(entry.Length==Num(row["bytes"])&&entry.Length>0&&entry.Length<=4*1024*1024&&total<=8*1024*1024-entry.Length,"bounded SQLite expansion");total+=entry.Length;string target=Safe(inputs,entry.FullName);Directory.CreateDirectory(Path.GetDirectoryName(target));using(var source=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[8192];long nbytes=0;int n;while((n=source.Read(buffer,0,buffer.Length))>0){Check(nbytes<=entry.Length-n,"bounded ZIP copy");output.Write(buffer,0,n);nbytes+=n;}Check(nbytes==entry.Length,"complete ZIP copy");}Check(Hash(target)==Str(row,"sha256"),"extracted SQLite raw SHA");File.SetAttributes(target,FileAttributes.ReadOnly);}}
        Check(seen.SetEquals(declared.Keys)&&Binding(inputs).Count==70,"every original input exactly once");
    }

    static HelperResult Analyze(string source,string archive)
    {
        context=Path.GetFileName(archive);var before=Binding(source);analyses++;var result=Guard(token=>TelegramAnalysisService.AnalyzeSelected(archive,source,"",false,token,m=>{}));
        Check((result.Status=="complete"||result.Status=="partial")&&File.Exists(Path.Combine(archive,"messages.jsonl"))&&!File.Exists(Path.Combine(archive,"job.incomplete"))&&!Directory.Exists(archive+".work"),"actual public archive completion and cleanup");NoLimits(result.Warnings);Check(Same(before,Binding(source)),"selected originals unchanged");
        var acquisition=Rows(Read(Path.Combine(archive,"acquisition.json"))["Files"]);var files=File.Exists(source)?new[]{source}:Directory.GetFiles(source,"*",SearchOption.AllDirectories);if(Directory.Exists(source))Check(acquisition.Count==files.Length,"all selected files acquired");
        foreach(string file in files){var found=acquisition.Where(r=>String.Equals(Path.GetFullPath(Str(r,"OriginalPath")),file,StringComparison.OrdinalIgnoreCase)).ToList();Check(found.Count==1&&Str(found[0],"Status")=="complete"&&Num(found[0]["Size"])==new FileInfo(file).Length&&Str(found[0],"Sha256")==Hash(file),"exact acquisition size/hash");}
        Runs.Add(new{source=source,archive=archive,status=result.Status,native_records=result.NativeRecords,messages=result.Messages,readable_sources=result.ReadableSources,source_before=before,source_after=Binding(source)});return result;
    }
    static List<ArchiveMessage> Search(string archive,string query="",bool regex=false,string evidence="")
    {
        var result=new List<ArchiveMessage>();long total=-1;do{long offset=result.Count;var page=Guard(token=>ArchiveSearchService.Search(archive,"Telegram",query,evidence,offset,token,regex));Check((page.status=="complete"||page.status=="partial")&&page.records!=null&&page.offset==offset,"public search page");NoLimits(page.warnings);if(total<0)total=page.total;Check(total>=0&&total<=10000&&page.total==total&&(page.records.Count>0||total==0),"stable bounded search total");result.AddRange(page.records);}while(result.Count<total);Check(result.Count==total&&result.All(r=>!String.IsNullOrEmpty(r.archive_record_key))&&result.Select(r=>r.archive_record_key).Distinct().Count()==result.Count,"complete unique archive locators");return result;
    }
    static void Full(string archive,ArchiveMessage row)
    {
        long offset=0;var text=new StringBuilder();for(int i=0;i<65;i++){long at=offset;var page=Guard(token=>ArchiveSearchService.ReadPage(archive,row.archive_record_key,at,token));Check(page.status=="complete"&&page.text_offset==offset&&page.next_offset>=offset,"public exact fulltext protocol");text.Append(page.text);offset=page.next_offset;if(page.eof){Check(offset==page.text_length&&text.ToString()==row.text,"exact fulltext, including empty string without replacement text");if(row.text=="")Check(page.text==""&&page.text_length==0&&page.next_offset==0,"empty fulltext completes at zero");return;}Check(offset>at,"fulltext advances");}throw new Exception("Bounded fulltext exhausted");
    }
    static void Weak(IEnumerable<ArchiveMessage> rows)
    {
        foreach(var row in rows){Check(row.evidence_kind=="fragment"&&new[]{"memory_fragment","typed_tl_fragment","sqlite_residual_fragment","sqlite_wal_residual","sqlite_rollback_fragment"}.Contains(row.record_kind),"unattributed fragments remain separate");Check(row.chat_id==null&&row.chat_name==null&&row.message_id==null&&row.sender_id==null&&row.sender_name==null&&row.timestamp==null&&row.timestamp_raw==null&&row.deleted==null&&row.wal_proof==null&&row.rollback_content_authenticity_verified!=true,"fragment never borrows native chat/author/date/deletion proof");}
    }
    static string Key(ArchiveMessage row){return row.identity_scope+"|"+row.native_tl_body_sha256+"|"+Convert.ToString(row.message_id,CultureInfo.InvariantCulture)+"|"+row.text_field;}
    static void CurrentAndReimport()
    {
        string archive=Path.Combine(work,"current");var summary=Analyze(Path.Combine(inputs,"positive"),archive);var all=Search(archive);var native=all.Where(Native).ToList();Weak(all.Where(r=>!Native(r)));Check(summary.ReadableSources==14&&summary.NativeRecords==14&&summary.HistoryMessages==14&&native.Count==14&&summary.Messages==all.Count&&summary.FragmentRecords==all.Count-14&&summary.DeletedSupportedRecords==0,"explicit new policy retains all14 observed native records, including7 empty");
        var expectedSources=positives.Keys.ToDictionary(Source,name=>name,StringComparer.OrdinalIgnoreCase);var seen=new HashSet<string>();
        foreach(var row in native){string file=Path.GetFullPath(row.source_file);Check(expectedSources.ContainsKey(file),"exact selected native SQLite source");string name=expectedSources[file];var expected=positives[name];var sql=(Dictionary<string,object>)expected["exact_sql"];Check(seen.Add(name)&&row.text==Str(expected,"text")&&row.text_field=="message"&&Num(row.chat_id)==Num(sql["uid"])&&Num(row.message_id)==Num(sql["mid"]),"each native identity and exact empty/paired text once");Check(row.native_tl_body_sha256==Str(expected,"tl_body_sha256")&&row.source_sha256==Str(sqlite[name],"sha256")&&row.native_constructor=="0x7600b9d3"&&Num(row.native_layer)==232&&row.completeness=="supported_structure_complete","native wholebody/source/profile pin");Check(row.identity_scope=="telegram-db:"+Hash(Encoding.UTF8.GetBytes(file.Replace('/','\\').ToLowerInvariant()))&&row.source_record=="messages_v2(uid="+Num(sql["uid"])+",mid="+Num(sql["mid"])+")","exact account scope and SQL locator");DateTimeOffset timestamp;Check(DateTimeOffset.TryParse(row.timestamp as string,CultureInfo.InvariantCulture,DateTimeStyles.None,out timestamp)&&timestamp.ToUniversalTime()==new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero).AddSeconds(Num(sql["date"]))&&Convert.ToString(row.sender_id,CultureInfo.InvariantCulture)=="user:77","observed author/date preserved");Check(row.chat_name==null&&row.sender_name==null&&row.deleted==null&&row.evidence_kind=="backup"&&row.provenance_verification!="provided_archive_metadata","unknown names/deletion remain unknown");bool cached=Get(expected,"known_valid_png_thumbnail") is bool&&(bool)expected["known_valid_png_thumbnail"];Check(row.media_kind=="document"&&row.media_id==Str(expected,"document_id")&&Num(row.thumbnail_count)==(cached?1:0)&&row.media_status==(cached?"cached_thumbnail_available":"document_reference_only")&&(row.attachments??new string[0]).Length==(cached?1:0),"explicit reference-only missing original vs cached thumbnail");if(cached)Check(Hash(Safe(archive,row.attachments[0]))==Hash(Convert.FromBase64String(Png)),"exact cached70B PNG");Full(archive,row);}
        Check(seen.SetEquals(positives.Keys)&&native.Count(r=>r.text=="")==7,"all14 independent identities and exactly7 zero-text records");
        foreach(var query in new[]{new[]{"Paired","literal"},new[]{"Paired[\\s\\S]*第二行","regex"}}){bool regex=query[1]=="regex";var found=Search(archive,query[0],regex).Where(Native).ToList();var expected=positives.Values.Where(r=>regex?Regex.IsMatch(Str(r,"text"),query[0]):Str(r,"text").IndexOf(query[0],StringComparison.OrdinalIgnoreCase)>=0).Select(r=>Str(r,"tl_body_sha256"));Check(found.Count==7&&new HashSet<string>(found.Select(r=>r.native_tl_body_sha256)).SetEquals(expected),"keyword/Regex searches exact caption text and do not manufacture text for media-only records");}
        foreach(string word in new[]{"METADATA_FILENAME_NOT_MESSAGE_","METADATA_TITLE_","METADATA_PERFORMER_","NEVER_OPEN_MEDIA_ORACLE_"})Check(!Search(archive,word).Any(Native),"filename/attributes/attachPath never become message text");Check(Search(archive,"",false,"deleted").Count==0,"surviving native metadata does not prove deletion");
        var attachments=Rows(Read(Path.Combine(archive,"attachment-metadata.json"))["attachments"]);Check(attachments.Count==1&&Str(attachments[0],"kind")=="cached_thumbnail"&&Num(attachments[0]["size"])==70&&Str(attachments[0],"sha256")==Hash(Convert.FromBase64String(Png)),"one content-deduplicated thumbnail, no restored original attachment");var origins=Rows(attachments[0]["sources"]);Check(origins.Count==2,"both empty and paired cached-thumbnail origins retained");foreach(string name in new[]{"empty-cached-png","paired-cached-png"}){var found=origins.Where(r=>String.Equals(Path.GetFullPath(Str(r,"source_file")),Source(name),StringComparison.OrdinalIgnoreCase)&&Str(r,"source_record").EndsWith("/document.thumbs[0]",StringComparison.Ordinal)).ToList();Check(found.Count==1&&Str(found[0],"source_sha256")==Str(sqlite[name],"sha256")&&Str(found[0],"offset_kind")=="sqlite_tl_blob_relative","known native thumbnail origin");byte[] blob=Convert.FromBase64String(Str(positives[name],"blob_base64"));int at=(int)Num(found[0]["blob_offset"]);Check(at>=0&&at<=blob.Length-70&&blob.Skip(at).Take(70).SequenceEqual(Convert.FromBase64String(Png)),"native blob thumbnail range replay");}
        var archiveBefore=Binding(archive);string imported=Path.Combine(work,"reimport");Analyze(Path.Combine(archive,"messages.jsonl"),imported);var copied=Search(imported).Where(r=>r.record_kind=="tl_message").ToList();var originals=native.ToDictionary(Key);Check(copied.Count==14&&new HashSet<string>(copied.Select(Key)).SetEquals(originals.Keys)&&copied.Count(r=>r.text=="")==7,"canonical reimport preserves exact14 identities and7 empty texts");foreach(var row in copied){Check(row.text==originals[Key(row)].text&&row.native_tl_body_sha256==originals[Key(row)].native_tl_body_sha256&&row.provenance_verification=="provided_archive_metadata"&&!Native(row)&&row.deleted==null,"provided archive retains text/metadata without becoming freshly verified native attribution or deletion");Full(imported,row);}Check(Same(archiveBefore,Binding(archive)),"search/fulltext/reimport never change original archive");
    }
    static void NegativesAndDump()
    {
        string archive=Path.Combine(work,"controls");var summary=Analyze(Path.Combine(inputs,"controls"),archive);var rows=Search(archive);Check(summary.ReadableSources==56&&summary.NativeRecords==0&&summary.HistoryMessages==0&&!rows.Any(Native)&&summary.DeletedSupportedRecords==0,"all56 bounded malformed/SQL-scope controls yield zero native history");Weak(rows);
        string root=Path.Combine(work,"owned-dump"),folder=Path.Combine(root,".hidden","cache"),file=Path.Combine(folder,"memory.bin");Directory.CreateDirectory(folder);File.SetAttributes(Directory.GetParent(folder).FullName,FileAttributes.Hidden);var expected=positives["paired-video"];byte[] blob=Convert.FromBase64String(Str(expected,"blob_base64"));using(var output=new FileStream(file,FileMode.CreateNew)){output.Write(new byte[513],0,513);output.Write(blob,0,blob.Length);output.Write(new byte[200],0,200);}File.SetAttributes(file,FileAttributes.ReadOnly|FileAttributes.Hidden);Check((File.GetAttributes(file)&FileAttributes.Hidden)!=0,"actual Windows-hidden bounded dump");archive=Path.Combine(work,"hidden-memory");summary=Analyze(root,archive);rows=Search(archive);Check(summary.NativeRecords==0&&!rows.Any(Native),"unbound memory bytes never become SQL-backed history");Weak(rows);var typed=rows.Where(r=>r.record_kind=="typed_tl_fragment"&&r.native_tl_body_sha256==Str(expected,"tl_body_sha256")).ToList();Check(typed.Count==1&&typed[0].text==Str(expected,"text")&&Num(typed[0].byte_offset)==513&&Num(typed[0].byte_length)==Num(expected["tl_bytes"])&&typed[0].source_sha256==Hash(file),"exact unassigned structured dump fragment/body/range/hash");Full(archive,typed[0]);
    }
    static Dictionary<string,string> Sources(){var result=Binding(Path.Combine(project,"tests","fixtures","telegram-media-only"));foreach(string name in new[]{"tests/TelegramMediaOnlyPortableTests.cs","tests/build_telegram_media_only_fixtures.py","helpers/recovery_engine/telegram_tl.py","helpers/recovery_engine/telegram_auto.py","helpers/recovery_engine/engine.py","helpers/recovery_engine/telegram_html.py","helpers/recovery_engine/archive_search.py","helpers/recovery_engine/archive_text.py","src/Recovery/Infrastructure/TelegramAnalysisService.cs","src/Recovery/UI/ArchiveSearchPanel.cs","src/Recovery/Archive/ArchiveContracts.cs","src/Recovery/Infrastructure/ArchiveSearchService.cs"})result.Add("@source/"+name,Hash(Safe(project,name)));return result;}
    static Dictionary<string,string> Runtime(string helper,string app,string harness){var result=Binding(Path.GetDirectoryName(helper));foreach(string file in new[]{app,harness,app+".config",harness+".config"}){Plain(file);result.Add("@entry/"+Path.GetFileName(file),Hash(file));}return result;}
    public static int Main(string[] args)
    {
        Exception failure=null;Dictionary<string,string> sourceBefore=null,sourceAfter=null,inputBefore=null,inputAfter=null,runtimeBefore=null,runtimeAfter=null;string helper=null,app=null,harness=null;CancellationTokenSource stop=null;
        try{if(args.Length!=1)throw new ArgumentException("Expected project directory");project=Path.GetFullPath(args[0]);work=Path.Combine(project,".build","telegram-media-only-portable-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);inputs=Path.Combine(work,"inputs");stop=new CancellationTokenSource(TimeSpan.FromMinutes(10));phase=stop.Token;clock=Stopwatch.StartNew();sourceBefore=Sources();Extract();inputBefore=Binding(inputs);helper=HelperClient.Executable;app=typeof(RecoveryCore).Assembly.Location;harness=typeof(TelegramMediaOnlyPortableTests).Assembly.Location;runtimeBefore=Runtime(helper,app,harness);CurrentAndReimport();NegativesAndDump();phase.ThrowIfCancellationRequested();}
        catch(Exception error){failure=error;}
