        if(failure!=null){Console.Error.WriteLine(failure);return 1;}Console.WriteLine("PASS TelegramMediaOnlyPortable: "+checks+" checks;14 native metadata records/7 exact-empty texts,56 controls/zero native,one70B thumbnail/two origins,keyword/Regex/fulltext,canonical reimport,unbound hidden dump and immutable bindings. No device or paid-tool claim.");return 0;
